SELECT n.notification_id, n.title, n.content, n.sender_id, n.sender_name, n.jump_url, n.attachment_urls, n.status, n.reply_deadline, n.create_by, n.create_time, n.update_by, n.update_time, n.remark, r.read_id, r.is_read, r.send_record_id, r.send_status FROM notification_user_read_record r INNER JOIN notification_send_record s ON s.send_record_id = r.send_record_id INNER JOIN notification n ON n.notification_id = s.notification_id AND n.status = '1' WHERE r.user_id = #{userId} AND r.send_status = '1'
AND r.student_user_id = #{studentUserId}
ORDER BY n.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM notification_user_read_record r
WHERE r.user_id = #{userId}
  AND r.send_status = '1'
  AND (r.is_read = '0' OR r.is_read IS NULL)

  AND r.student_user_id = #{studentUserId}
